package com.galaxyos.gx;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.provider.Settings;import android.view.*;import android.widget.*;import java.util.*;

public class MainActivity extends Activity {
 int bg=0xff070d27, panel=0xff182451, accent=0xff9956ff; LinearLayout root,content,nav;
 GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{color,0xff10183a});d.setCornerRadius(radius);d.setStroke(2,0xff4856a2);return d;}
 TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextColor(-1);t.setTextSize(size);t.setPadding(16,12,16,12);return t;}
 LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
 void add(LinearLayout p,View v){p.addView(v,new LinearLayout.LayoutParams(-1,-2));}
 void button(LinearLayout p,String title,Runnable action){TextView b=text(title,17);b.setFocusable(true);b.setBackground(shape(panel,20));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(5,5,5,5);p.addView(b,lp);b.setOnClickListener(v->action.run());b.setOnFocusChangeListener((v,f)->b.setBackground(shape(f?accent:panel,20)));}
 void system(String action){try{startActivity(new Intent(action));}catch(Exception e){Toast.makeText(this,"Bu cihazda desteklenmiyor",Toast.LENGTH_SHORT).show();}}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility(5894|1024|512);home();}
 void frame(String heading){root=column();root.setBackgroundColor(bg);setContentView(root);TextView h=text("◉ GalaxyOS GX     "+heading+"       ◉ TV Box • Tablet Edition",22);h.setTypeface(null,Typeface.BOLD);add(root,h);ScrollView sc=new ScrollView(this);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout row=new LinearLayout(this);row.setPadding(14,5,14,12);sc.addView(row);nav=column();row.addView(nav,new LinearLayout.LayoutParams(220,-2));content=column();LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,1);cp.setMargins(18,0,0,0);row.addView(content,cp);button(nav,"⌂ Ana Ekran",()->home());button(nav,"▦ Uygulamalar",()->apps());button(nav,"⚙ GX Ayarlar",()->settingsPage());button(nav,"◉ Wi-Fi",()->system(Settings.ACTION_WIFI_SETTINGS));button(nav,"ᛒ Bluetooth",()->system(Settings.ACTION_BLUETOOTH_SETTINGS));button(nav,"▣ Depolama",()->system(Settings.ACTION_INTERNAL_STORAGE_SETTINGS));button(nav,"◈ Ekran",()->system(Settings.ACTION_DISPLAY_SETTINGS));}
 void home(){frame("Ana Ekran");TextView hero=text("GALAXYOS GX\n\nTV Box'unuzu tablet deneyimine dönüştürün\n\nLiquid Glass • Uygulamalar • GX Ayarlar",27);hero.setTypeface(null,Typeface.BOLD);hero.setMinHeight(180);hero.setBackground(shape(0xff311b78,30));add(content,hero);button(content,"▦ Tüm Uygulamaları Aç",()->apps());button(content,"⚙ GX Ayarlar",()->settingsPage());add(content,text("Hızlı Kontrol",23));button(content,"Wi-Fi Ayarları",()->system(Settings.ACTION_WIFI_SETTINGS));button(content,"Bluetooth Ayarları",()->system(Settings.ACTION_BLUETOOTH_SETTINGS));button(content,"Ekran Yansıtma / Cast",()->system(Settings.ACTION_CAST_SETTINGS));button(content,"Cihaz Bilgisi",()->system(Settings.ACTION_DEVICE_INFO_SETTINGS));}
 void apps(){frame("Uygulamalar");ArrayList<android.content.pm.ApplicationInfo> list=new ArrayList<>(getPackageManager().getInstalledApplications(0));Collections.sort(list,(a,b)->String.valueOf(getPackageManager().getApplicationLabel(a)).compareToIgnoreCase(String.valueOf(getPackageManager().getApplicationLabel(b))));for(android.content.pm.ApplicationInfo app:list){Intent launch=getPackageManager().getLaunchIntentForPackage(app.packageName);if(launch!=null)button(content,String.valueOf(getPackageManager().getApplicationLabel(app)),()->{try{startActivity(launch);}catch(Exception e){Toast.makeText(this,"Uygulama açılamadı",Toast.LENGTH_SHORT).show();}});}}
 void settingsPage(){frame("GX Ayarlar");TextView t=text("GX AYARLAR\nCihazınızın gerçek Android ayarlarını açın",26);t.setBackground(shape(0xff321c73,24));add(content,t);button(content,"Ağ ve İnternet",()->system(Settings.ACTION_WIRELESS_SETTINGS));button(content,"Wi-Fi",()->system(Settings.ACTION_WIFI_SETTINGS));button(content,"Bluetooth",()->system(Settings.ACTION_BLUETOOTH_SETTINGS));button(content,"Ekran",()->system(Settings.ACTION_DISPLAY_SETTINGS));button(content,"Ses",()->system(Settings.ACTION_SOUND_SETTINGS));button(content,"Depolama",()->system(Settings.ACTION_INTERNAL_STORAGE_SETTINGS));button(content,"Uygulama Yönetimi",()->system(Settings.ACTION_APPLICATION_SETTINGS));button(content,"Erişilebilirlik",()->system(Settings.ACTION_ACCESSIBILITY_SETTINGS));button(content,"Cihaz Hakkında",()->system(Settings.ACTION_DEVICE_INFO_SETTINGS));button(content,"Tüm Sistem Ayarları",()->system(Settings.ACTION_SETTINGS));}
 @Override public void onBackPressed(){home();}
}
